def get_principal(
    ctx: RequestContext,
    id_: "B2cId",
) -> Principal:
    """Retrieves a single principal by id.

    Arguments:
    ctx: RequestContext -- A request context object
    id_: "B2cId" -- The ID (uuid-style) of the principal to search for

    Returns:
    Details of the specified principal
    """

    path = "/v1/api/ulv2/directory/v1/principal/:id"
    path = path.replace(":id", str(id_), 1)

    params = dict()
    headers = dict()
    res = ctx.get(path, params=params, headers=headers)
    res_dict = json.loads(res)
    return Principal.from_dict(res_dict)

def get_principals(
    ctx: RequestContext,
    ids: str,
) -> List[Principal]:
    """Retrieves a list of principals specified by a comma-separated list of ids.

    Arguments:
    ctx: RequestContext -- A request context object
    ids: str -- The comma separated list of IDs (uuid-style) of the principals to search for

    Returns:
    Details of all the specified principals
    """

    path = "/v1/api/ulv2/directory/v1/principal/:ids"
    path = path.replace(":ids", str(ids), 1)

    params = dict()
    headers = dict()
    res = ctx.get(path, params=params, headers=headers)
    res_dict = json.loads(res)
    res_list = []
    for item in res_dict:
        res_list.append(Principal.from_dict(item))
    return res_list

def query_principals(
    ctx: RequestContext,
    query: str,
) -> List[Principal]:
    """Queries for principals. The query is performed as a substring match against the following fields:
    
    For users:
    - displayName
    - id
    - otherMails
    
    For groups:
    - displayName
    - id
    - description

    Arguments:
    ctx: RequestContext -- A request context object
    query: str -- The query string to search for

    Returns:
    A list of all matching directory principals.
    """

    path = "/v1/api/ulv2/directory/v1/principals/:query"
    path = path.replace(":query", str(query), 1)

    params = dict()
    headers = dict()
    res = ctx.get(path, params=params, headers=headers)
    res_dict = json.loads(res)
    res_list = []
    for item in res_dict:
        res_list.append(Principal.from_dict(item))
    return res_list

